CREATE TABLE IF NOT EXISTS admin(id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE,password VARCHAR(255),real_name VARCHAR(50),avatar VARCHAR(255),status INT,last_login_time TIMESTAMP,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE IF NOT EXISTS role(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50),code VARCHAR(50) UNIQUE,description VARCHAR(255),version BIGINT NOT NULL DEFAULT 0,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_role(id BIGINT AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT,role_id BIGINT,UNIQUE(admin_id,role_id));
